    Pp[f'gl_l{k}'] = g.gl.shift(-k); Pp[f'gf_l{k}'] = g.gf.shift(-k); Pp[f'd_l{k}'] = g.ins0.shift(-k)
Pp['gdec'] = Pp.gf.combine_first(Pp.gl)
Pp['g_prev'] = g.g_last.shift(1)
